/** Responsive photos of both concepts, generated by the draft-images integration. */
export const assetBase = "/examples/trades";

export interface Company {
  name: string;
  owner: string;
  ownerRole: string;
  street: string;
  /** A made-up town without postcode or coordinates, so the address points nowhere real. */
  city: string;
  /** Numbers from the Bundesnetzagentur's range for media productions, so nobody real is called. */
  phone: { display: string; href: string; e164: string };
  whatsapp: { display: string; href: string };
  /** `.example` is reserved for documentation and never delivers mail. */
  email: string;
  hours: { days: string; short: string; opens: string; closes: string }[];
  rating: { value: string; count: number };
  credentials: string;
  since: number;
}

export interface Review {
  author: string;
  quote: string;
  topic: string;
  stars: number;
}

export interface Faq {
  q: string;
  a: string[];
}
export interface Group {
  title: string;
  items: string[];
}

export interface Service {
  slug: string;
  name: string;
  nav: string;
  title: string;
  description: string;
  h1: string;
  intro: string[];
  summary: string;
  image: string;
  imageAlt: string;
  gallery: { name: string; alt: string }[];
  groups: Group[];
  points?: { title: string; items: string[]; sequence?: boolean };
  faqs: Faq[];
  formValue: string;
}

